<?php $__env->startPush('scripts'); ?><script>(()=>{const root=document.querySelector('[data-adaptive-publication]');if(!root)return;const type=root.querySelector('[data-publication-type]'),access=root.querySelector('[data-access-type]'),academic=root.querySelector('[data-academic-fields]'),series=root.querySelector('[data-series-fields]'),premium=root.querySelector('[data-premium-fields]');const update=()=>{const option=type.options[type.selectedIndex];academic.hidden=option?.dataset.academic!=='1';series.hidden=option?.dataset.series!=='1';premium.hidden=access.value!=='premium';};type.addEventListener('change',update);access.addEventListener('change',update);update();})();</script><?php $__env->stopPush(); ?>

